select tt.id,tt.template_name,tt.template_type,tt.using_unit_name,tt.contract_type,tt.create_by,tt.create_time,ta.file_name,ta.file_url,tt.attachment_id
from tb_template tt
left join tb_attachment ta on tt.attachment_id = ta.id


        tt.template_type = #{queryVO.templateType,jdbcType=INTEGER}


        and tt.template_name like concat('%',#{queryVO.templateName,jdbcType=VARCHAR},'%')


        and tt.contract_type = #{queryVO.contractType,jdbcType=VARCHAR}


        and tt.using_unit_no in

            #{item, jdbcType=VARCHAR}


    and tt.del_flag = 0

order by tt.create_time desc

select tt.id,tt.template_name,tt.template_type,tt.using_unit_name,tt.contract_type,tt.create_by,tt.create_time,ta.file_name,ta.file_url,tt.attachment_id
from tb_template tt  left join tb_attachment ta on tt.attachment_id = ta.id

    using_unit_no in

        #{ids}


        and tt.template_type = #{queryVO.templateType,jdbcType=INTEGER}


        and tt.template_name like concat('%',#{queryVO.templateName,jdbcType=VARCHAR},'%')


        and tt.contract_type = #{queryVO.contractType,jdbcType=VARCHAR}

    and tt.del_flag = 0

GROUP BY tt.id
order by tt.create_time desc
